import { useEffect, useState } from "react";
import UsersForm from "./UsersForm";
import API_URL from "../api";

export default function UserRoleManagement() {
  const [usuarios, setUsuarios] = useState([]);

  const cargarUsuarios = async () => {
    try {
      const res = await fetch(`${API_URL}/usuarios`);
      if (!res.ok) {
        throw new Error(`Error al cargar usuarios: ${res.status} ${res.statusText}`);
      }
      const data = await res.json();
      setUsuarios(data);
    } catch (error) {
      console.error(error);
      alert("No se pudo cargar los usuarios. Asegúrate de que el servidor API esté ejecutándose en localhost:3004.");
    }
  };

  useEffect(() => {
    cargarUsuarios();
  }, []);

  const cambiarRol = async (email) => {
    const usuario = usuarios.find(u => u.email === email);
    if (!usuario) return;

    const nuevoRol = usuario.rol === "admin" ? "user" : "admin";

    try {
      const res = await fetch(`${API_URL}/usuarios/${usuario.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ rol: nuevoRol })
      });

      if (!res.ok) {
        throw new Error(`Error al cambiar el rol: ${res.status} ${res.statusText}`);
      }

      cargarUsuarios();
    } catch (error) {
      console.error(error);
      alert("No se pudo cambiar el rol. Revisa que el servidor API esté disponible.");
    }
  };

  return (
    <div>
      <h2>Gestión de usuarios</h2>

      <UsersForm onAdd={cargarUsuarios} />

      <table className="table table-striped mt-4">
        <thead>
          <tr>
            <th>Email</th>
            <th>Rol</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {usuarios.map(u => (
            <tr key={u.id}>
              <td>{u.email}</td>
              <td>{u.rol}</td>
              <td>
                <button className="btn btn-primary btn-sm" onClick={() => cambiarRol(u.email)}>
                  Cambiar rol
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
